class Solution:
    def maximizeSum(self, nums: list[int], k: int) -> int:
        def f(x: int) -> int:
            cnt = [0] * 10
            while x:
                x, v = divmod(x, 10)
                cnt[v] += 1
            y = 0
            for i in range(9, -1, -1):
                for _ in range(cnt[i]):
                    y = y * 10 + i
            return y

        n = len(nums)
        t = [f(x) for x in nums]
        ids = list(range(n))
        ids.sort(key=lambda i: t[i] - nums[i], reverse=True)
        return sum(t[ids[i]] if i < k else nums[ids[i]] for i in range(n))

class Solution {
    public long maximizeSum(int[] nums, int k) {
        int n = nums.length;
        int[] t = new int[n];
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            int[] cnt = new int[10];
            while (x > 0) {
                int v = x % 10;
                x /= 10;
                cnt[v]++;
            }
            int y = 0;
            for (int j = 9; j >= 0; j--) {
                for (int c = 0; c < cnt[j]; c++) {
                    y = y * 10 + j;
                }
            }
            t[i] = y;
        }
        Integer[] ids = new Integer[n];
        Arrays.setAll(ids, i -> i);
        Arrays.sort(ids, (i, j) -> Integer.compare(t[j] - nums[j], t[i] - nums[i]));
        long ans = 0;
        for (int i = 0; i < n; i++) {
            int x = nums[ids[i]];
            ans += i < k ? t[ids[i]] : x;
        }
        return ans;
    }
}

class Solution {
public:
    long long maximizeSum(vector<int>& nums, int k) {
        auto f = [](int x) {
            int cnt[10] = {};
            while (x) {
                int v = x % 10;
                x /= 10;
                cnt[v]++;
            }
            int y = 0;
            for (int i = 9; i >= 0; i--) {
                for (int j = 0; j < cnt[i]; j++) {
                    y = y * 10 + i;
                }
            }
            return y;
        };
        int n = nums.size();
        vector<int> t(n);
        vector<int> ids(n);
        iota(ids.begin(), ids.end(), 0);
        for (int i = 0; i < n; i++) {
            t[i] = f(nums[i]);
        }
        sort(ids.begin(), ids.end(), [&](int i, int j) {
            return t[i] - nums[i] > t[j] - nums[j];
        });
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            int x = nums[ids[i]];
            ans += i < k ? t[ids[i]] : x;
        }
        return ans;
    }
};

func maximizeSum(nums []int, k int) int64 {
	f := func(x int) int {
		cnt := [10]int{}
		for x > 0 {
			v := x % 10
			x /= 10
			cnt[v]++
		}
		y := 0
		for i := 9; i >= 0; i-- {
			for j := 0; j < cnt[i]; j++ {
				y = y*10 + i
			}
		}
		return y
	}
	n := len(nums)
	t := make([]int, n)
	ids := make([]int, n)
	for i, x := range nums {
		t[i] = f(x)
		ids[i] = i
	}
	sort.Slice(ids, func(i, j int) bool {
		return t[ids[i]]-nums[ids[i]] > t[ids[j]]-nums[ids[j]]
	})
	var ans int64
	for i := 0; i < n; i++ {
		x := nums[ids[i]]
		if i < k {
			ans += int64(t[ids[i]])
		} else {
			ans += int64(x)
		}
	}
	return ans
}

function maximizeSum(nums: number[], k: number): number {
    const f = (x: number): number => {
        const cnt = Array(10).fill(0);
        while (x > 0) {
            const v = x % 10;
            x = Math.floor(x / 10);
            cnt[v]++;
        }
        let y = 0;
        for (let i = 9; i >= 0; i--) {
            for (let j = 0; j < cnt[i]; j++) {
                y = y * 10 + i;
            }
        }
        return y;
    };
    const n = nums.length;
    const t = nums.map(x => f(x));
    const ids = Array.from({ length: n }, (_, i) => i);
    ids.sort((i, j) => t[j] - nums[j] - (t[i] - nums[i]));
    let ans = 0;
    for (let i = 0; i < n; i++) {
        const x = nums[ids[i]];
        ans += i < k ? t[ids[i]] : x;
    }
    return ans;
}
